function humanRial(value){if(value==null||!Number.isFinite(Number(value)))return'—';const amount=Number(value),abs=Math.abs(amount);if(abs>=1e12)return`${fa(amount/1e12)} هزار میلیارد ریال`;if(abs>=1e9)return`${fa(amount/1e9)} میلیارد ریال`;if(abs>=1e6)return`${fa(amount/1e6)} میلیون ریال`;return`${fa(Math.round(amount))} ریال`;}
