function renderMarketReport(report){const root=$('#marketReportContent');if(!report){root.innerHTML='<div class="empty">گزارشی موجود نیست.</div>';return;}const rows=report.items||[];root.innerHTML=`<div class="report-head"><div><h2 class="tone-${esc(report.tone)}">${esc(report.title)}</h2><p class="note">${esc(report.description)}</p></div><span class="tag">حداکثر ۱۰ نماد</span></div>${rows.length?`<div class="table-wrap"><table class="table dashboard-table"><thead><tr><th>رتبه</th><th>نماد</th><th>قیمت / تغییر</th><th>حجم / قدرت</th><th>P/E</th><th>سبد</th><th>دلایل رتبه</th></tr></thead><tbody>${rows.map((item,index)=>`<tr data-dashboard-symbol="${esc(item.symbol)}"><td>${fa(index+1)}</td><td><span class="dashboard-symbol"><b>${esc(item.symbol)}</b><small>${esc(item.name||'')}</small></span></td><td>${dashboardMetric(item.price,' ریال')}<br><small class="${item.changePct>=0?'profit-positive':'profit-negative'}">${item.changePct==null?'—':`${item.changePct>=0?'+':''}${fa(item.changePct)}٪`}</small></td><td>${item.volumeRatio==null?'—':`${fa(item.volumeRatio)}× میانگین`}<br><small>قدرت: ${dashboardMetric(item.buyerPower)}</small></td><td>${dashboardMetric(item.pe)}<br><small>گروه: ${dashboardMetric(item.groupPe)}</small></td><td>${item.position?`${fa(item.position.quantity)} سهم<br><small class="${item.position.profitPct>=0?'profit-positive':'profit-negative'}">${item.position.profitPct>=0?'+':''}${fa(item.position.profitPct)}٪</small>`:'—'}</td><td><div class="reason-list">${(item.reasons||[]).map(text=>`<span>${persianDigits(esc(text))}</span>`).join('')}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">در Snapshot فعلی هیچ نمادی تمام شروط این گزارش را ندارد.</div>`}`;root.querySelectorAll('[data-dashboard-symbol]').forEach(row=>row.onclick=()=>openSymbolProfile(row.dataset.dashboardSymbol));}
async function loadMarketDashboard(){const root=$('#marketReportContent'),button=$('#reloadMarketDashboard');root.innerHTML='<div class="empty">در حال رتبه‌بندی Snapshot بازار و محاسبه محلی اندیکاتورها…</div>';button.disabled=true;try{renderMarketDashboard(await api(`/api/market-dashboard?scope=${marketDashboardScope}`));}catch(error){root.innerHTML=`<div class="empty">${esc(error.message)}</div>`;msg(error.message,'error');}finally{button.disabled=false;}}
