function tehranParts(date=new Date()){return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));}
function jalaliInput(date){const p=tehranParts(date),j=Jalali.toJalaali(Number(p.year),Number(p.month),Number(p.day));return `${fa(j.jy)}/${fa(String(j.jm).padStart(2,'0'))}/${fa(String(j.jd).padStart(2,'0'))} ${fa(p.hour)}:${fa(p.minute)}`;}
function tehranIso(value){const match=/^(\d{4})\/(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{2})$/.exec(latin(value));if(!match)throw new Error('تاریخ و ساعت شمسی را انتخاب کنید.');const g=Jalali.toGregorian(Number(match[1]),Number(match[2]),Number(match[3]));return new Date(`${g.gy}-${String(g.gm).padStart(2,'0')}-${String(g.gd).padStart(2,'0')}T${String(match[4]).padStart(2,'0')}:${match[5]}:00+03:30`).toISOString();}
function dateAtTehran(base,hour,minute){const p=tehranParts(base);return new Date(`${p.year}-${p.month}-${p.day}T${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}:00+03:30`);}
function weekday(date){return new Intl.DateTimeFormat('en-US',{timeZone:tz,weekday:'short'}).format(date);}
const tradingDays=new Set(['Sat','Sun','Mon','Tue','Wed']);
function nextTradingDate(now=new Date()){let d=new Date(now);do{d=new Date(d.getTime()+86400000);}while(!tradingDays.has(weekday(d)));return d;}
function nextSaturday(now=new Date()){let d=new Date(now);do{d=new Date(d.getTime()+86400000);}while(weekday(d)!=='Sat');return d;}
function setDateInput(id,date){$(id).value=jalaliInput(date);}
function setDefaults(){setDateInput('#startAt',new Date());setDateInput('#endAt',new Date(Date.now()+60*60000));}setDefaults();
$$('[data-time]').forEach(btn=>btn.onclick=()=>{const [target,preset]=btn.dataset.time.split(':'),now=new Date();let value=now;if(preset==='0930')value=dateAtTehran(now,9,30);if(preset==='next0930')value=dateAtTehran(nextTradingDate(now),9,30);if(preset==='sat0930')value=dateAtTehran(nextSaturday(now),9,30);if(preset==='30')value=new Date(now.getTime()+30*60000);if(preset==='60')value=new Date(now.getTime()+60*60000);if(preset==='close')value=dateAtTehran(tradingDays.has(weekday(now))?now:nextTradingDate(now),12,30);if(preset==='nextclose')value=dateAtTehran(nextTradingDate(now),12,30);if(preset==='satclose')value=dateAtTehran(nextSaturday(now),12,30);if(preset==='week')value=new Date(now.getTime()+7*86400000);setDateInput(`#${target}At`,value);});

const monthNames=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'],calendar={target:null,jy:0,jm:0,jd:0,time:'09:30'};
function closeCalendar(){$('#calendarPop').classList.add('hidden');calendar.target=null;}
function openCalendar(input){let date=new Date();try{date=new Date(tehranIso(input.value));}catch{}const p=tehranParts(date),j=Jalali.toJalaali(Number(p.year),Number(p.month),Number(p.day));Object.assign(calendar,{target:input,jy:j.jy,jm:j.jm,jd:j.jd,time:`${p.hour}:${p.minute}`});renderCalendar();const rect=input.getBoundingClientRect(),pop=$('#calendarPop');pop.classList.remove('hidden');pop.style.top=`${Math.min(innerHeight-pop.offsetHeight-12,rect.bottom+7)}px`;pop.style.left=`${Math.max(12,Math.min(innerWidth-pop.offsetWidth-12,rect.left))}px`;}
function renderCalendar(){const first=Jalali.toGregorian(calendar.jy,calendar.jm,1),firstDay=new Date(`${first.gy}-${String(first.gm).padStart(2,'0')}-${String(first.gd).padStart(2,'0')}T12:00:00+03:30`).getUTCDay(),offset=(firstDay+1)%7,len=Jalali.monthLength(calendar.jy,calendar.jm),days=Array.from({length:offset},()=>'<span></span>').concat(Array.from({length:len},(_,i)=>`<button data-cal-day="${i+1}" class="${i+1===calendar.jd?'selected':''}">${fa(i+1)}</button>`)).join(''),pop=$('#calendarPop');pop.innerHTML=`<div class="calendar-head"><button data-cal-next aria-label="ماه بعد">‹</button><strong>${monthNames[calendar.jm-1]} ${fa(calendar.jy)}</strong><button data-cal-prev aria-label="ماه قبل">›</button></div><div class="calendar-week">${['ش','ی','د','س','چ','پ','ج'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-days">${days}</div><div class="calendar-foot"><div class="calendar-time"><span>ساعت</span><input id="calendarTime" type="time" value="${calendar.time}"></div><div><button data-cal-today>امروز</button> <button data-cal-close>بستن</button></div></div>`;pop.querySelector('[data-cal-prev]').onclick=()=>{calendar.jm--;if(calendar.jm<1){calendar.jm=12;calendar.jy--;}calendar.jd=Math.min(calendar.jd,Jalali.monthLength(calendar.jy,calendar.jm));renderCalendar();};pop.querySelector('[data-cal-next]').onclick=()=>{calendar.jm++;if(calendar.jm>12){calendar.jm=1;calendar.jy++;}calendar.jd=Math.min(calendar.jd,Jalali.monthLength(calendar.jy,calendar.jm));renderCalendar();};pop.querySelectorAll('[data-cal-day]').forEach(b=>b.onclick=()=>{calendar.jd=Number(b.dataset.calDay);calendar.time=$('#calendarTime').value||'09:30';calendar.target.value=`${fa(calendar.jy)}/${fa(String(calendar.jm).padStart(2,'0'))}/${fa(String(calendar.jd).padStart(2,'0'))} ${fa(calendar.time.slice(0,2))}:${fa(calendar.time.slice(3))}`;closeCalendar();});pop.querySelector('[data-cal-today]').onclick=()=>{const p=tehranParts(new Date()),j=Jalali.toJalaali(Number(p.year),Number(p.month),Number(p.day));Object.assign(calendar,{jy:j.jy,jm:j.jm,jd:j.jd,time:`${p.hour}:${p.minute}`});renderCalendar();};pop.querySelector('[data-cal-close]').onclick=closeCalendar;}
