function switchMode(next){mode=next;$('#textMode').classList.toggle('hidden',next!=='text');$('#builderMode').classList.toggle('hidden',next!=='builder');$('#indicatorBuilderMode').classList.toggle('hidden',next!=='v2');$('#textTab').classList.toggle('active',next==='text');$('#builderTab').classList.toggle('active',next==='builder');$('#indicatorBuilderTab').classList.toggle('active',next==='v2');}$('#textTab').onclick=()=>switchMode('text');$('#builderTab').onclick=()=>switchMode('builder');$('#indicatorBuilderTab').onclick=()=>switchMode('v2');
function fieldOptions(selected){return meta.fields.map(x=>`<option value="${x.value}" ${x.value===selected?'selected':''}>${esc(x.label)}</option>`).join('');}function opOptions(field,selected){return meta.rules.filter(x=>x.fields.includes(field)).map(x=>`<option value="${x.operator}" ${x.operator===selected?'selected':''}>${esc(x.label)}</option>`).join('');}
function getNode(path){return path.reduce((n,i)=>n.children[i],tree);}function parsePath(value){return value===''?[]:value.split('.').map(Number);}function removeNode(path){getNode(path.slice(0,-1)).children.splice(path.at(-1),1);renderBuilder();}
function renderNode(node,path=[]){if(node.type==='group')return `<div class="group"><div class="group-head"><select data-group="${path.join('.')}"><option value="AND" ${node.op==='AND'?'selected':''}>همه شروط (AND)</option><option value="OR" ${node.op==='OR'?'selected':''}>حداقل یک شرط (OR)</option></select><div class="actions"><button class="secondary small" data-add-rule="${path.join('.')}">+ قاعده</button><button class="secondary small" data-add-group="${path.join('.')}">+ گروه</button>${path.length?`<button class="danger small" data-remove="${path.join('.')}">حذف</button>`:''}</div></div><div class="group-body">${node.children.map((x,i)=>renderNode(x,[...path,i])).join('')}</div></div>`;const d=meta.rules.find(x=>x.operator===node.operator)||{};return `<div class="rule-row"><select data-field="${path.join('.')}">${fieldOptions(node.field)}</select><select data-op="${path.join('.')}">${opOptions(node.field,node.operator)}</select>${d.needsRange?`<input data-min="${path.join('.')}" type="number" value="${node.min??''}" placeholder="از"><input data-max="${path.join('.')}" type="number" value="${node.max??''}" placeholder="تا">`:d.needsValue?`<input data-value="${path.join('.')}" type="number" step="any" value="${node.value??''}" placeholder="مقدار"><input data-samples="${path.join('.')}" type="number" value="${node.options?.samples||3}" title="تعداد نمونه">`:'<span></span><span></span>'}<button class="danger small" data-remove="${path.join('.')}">حذف</button></div>`;}
function bindBuilder(){$$('[data-group]').forEach(el=>el.onchange=()=>getNode(parsePath(el.dataset.group)).op=el.value);$$('[data-field]').forEach(el=>el.onchange=()=>{const n=getNode(parsePath(el.dataset.field));n.field=el.value;n.operator=meta.rules.find(x=>x.fields.includes(el.value))?.operator||'gt';renderBuilder();});$$('[data-op]').forEach(el=>el.onchange=()=>{getNode(parsePath(el.dataset.op)).operator=el.value;renderBuilder();});for(const key of ['value','min','max'])$$(`[data-${key}]`).forEach(el=>el.oninput=()=>getNode(parsePath(el.dataset[key]))[key]=Number(el.value));$$('[data-samples]').forEach(el=>el.oninput=()=>{const n=getNode(parsePath(el.dataset.samples));n.options={...(n.options||{}),samples:Number(el.value),minutes:15};});$$('[data-add-rule]').forEach(el=>el.onclick=()=>{getNode(parsePath(el.dataset.addRule)).children.push({type:'rule',field:'lastPrice',operator:'gt',value:0});renderBuilder();});$$('[data-add-group]').forEach(el=>el.onclick=()=>{getNode(parsePath(el.dataset.addGroup)).children.push({type:'group',op:'AND',children:[{type:'rule',field:'lastPrice',operator:'gt',value:0}]});renderBuilder();});$$('[data-remove]').forEach(el=>el.onclick=()=>removeNode(parsePath(el.dataset.remove)));}
function renderBuilder(){$('#builder').innerHTML=renderNode(tree);bindBuilder();}

function v2Definition(name){return (meta.conditionDefinitionsV2||[]).find(x=>x.value===name)||{value:name,label:name,params:[]};}
function v2Options(selected){return (meta.conditionDefinitionsV2||[]).map(x=>`<option value="${esc(x.value)}" ${x.value===selected?'selected':''}>${esc(x.label)}</option>`).join('');}
function v2GetNode(path){return path.reduce((node,index)=>node.children[index],v2Tree);}
function v2Remove(path){v2GetNode(path.slice(0,-1)).children.splice(path.at(-1),1);renderV2Builder();}
function renderV2Node(node,path=[]){if(node.type==='group')return `<div class="group"><div class="group-head"><select data-v2-group="${path.join('.')}"><option value="AND" ${node.logic==='AND'?'selected':''}>همه شروط (AND)</option><option value="OR" ${node.logic==='OR'?'selected':''}>حداقل یک شرط (OR)</option><option value="AT_LEAST" ${node.logic==='AT_LEAST'?'selected':''}>حداقل N شرط</option></select>${node.logic==='AT_LEAST'?`<input data-v2-min-matches="${path.join('.')}" type="number" min="1" max="${node.children.length}" value="${node.minMatches||1}" title="حداقل تعداد تطبیق">`:''}<div class="actions"><button class="secondary small" data-v2-add-condition="${path.join('.')}">+ شرط</button><button class="secondary small" data-v2-add-group="${path.join('.')}">+ گروه</button>${path.length?`<button class="danger small" data-v2-remove="${path.join('.')}">حذف</button>`:''}</div></div><div class="group-body">${node.children.map((child,index)=>renderV2Node(child,[...path,index])).join('')}</div></div>`;const definition=v2Definition(node.name),inputs=definition.params.map(param=>`<input data-v2-param="${path.join('.')}:${esc(param.key)}" type="number" step="any" value="${node.params?.[param.key]??param.default??''}" placeholder="${esc(param.label)}" title="${esc(param.label)}">`).join('');return `<div class="rule-row v2-rule-row"><select data-v2-condition="${path.join('.')}">${v2Options(node.name)}</select>${inputs}<span></span><button class="danger small" data-v2-remove="${path.join('.')}">حذف</button></div>`;}
function bindV2Builder(){$$('[data-v2-group]').forEach(el=>el.onchange=()=>{const node=v2GetNode(parsePath(el.dataset.v2Group));node.logic=el.value;if(el.value==='AT_LEAST')node.minMatches=Math.min(2,node.children.length);else delete node.minMatches;renderV2Builder();});$$('[data-v2-min-matches]').forEach(el=>el.oninput=()=>v2GetNode(parsePath(el.dataset.v2MinMatches)).minMatches=Number(el.value));$$('[data-v2-condition]').forEach(el=>el.onchange=()=>{const node=v2GetNode(parsePath(el.dataset.v2Condition)),definition=v2Definition(el.value);node.name=el.value;node.params=Object.fromEntries(definition.params.map(param=>[param.key,param.default??0]));renderV2Builder();});$$('[data-v2-param]').forEach(el=>el.oninput=()=>{const [path,key]=el.dataset.v2Param.split(':');v2GetNode(parsePath(path)).params[key]=Number(el.value);});$$('[data-v2-add-condition]').forEach(el=>el.onclick=()=>{v2GetNode(parsePath(el.dataset.v2AddCondition)).children.push({type:'condition',name:'MACD_RECOVERY_EARLY',params:{}});renderV2Builder();});$$('[data-v2-add-group]').forEach(el=>el.onclick=()=>{v2GetNode(parsePath(el.dataset.v2AddGroup)).children.push({type:'group',logic:'AND',children:[{type:'condition',name:'MACD_RECOVERY_EARLY',params:{}}]});renderV2Builder();});$$('[data-v2-remove]').forEach(el=>el.onclick=()=>v2Remove(parsePath(el.dataset.v2Remove)));}
function renderV2Builder(){$('#v2Builder').innerHTML=renderV2Node(v2Tree);bindV2Builder();}

function renderQuote(data,target='#quoteContent'){const el=$(target);if(!data){el.innerHTML='<div class="empty">داده‌ای ثبت نشده است.</div>';return;}el.innerHTML=`<div><span>آخرین قیمت</span><strong>${fa(data.lastPrice)} ریال</strong></div><div><span>پایانی</span><strong>${fa(data.closePrice)} ریال</strong></div><div><span>حد پایین</span><strong>${fa(data.lowerLimit)} ریال</strong></div><div><span>حد بالا</span><strong>${fa(data.upperLimit)} ریال</strong></div><div><span>وضعیت</span><strong>${esc(data.state||'—')}</strong></div><div><span>زمان داده</span><strong>${fmtDate(data.updatedAt)}</strong></div>`;}
function signalClass(status=''){return /مثبت|قوی|بهبود|صعودی|بالاتر|ورود|کراس|خروج اولیه/.test(status)?'signal-positive':/ضعیف|منفی|نزولی|پایین‌تر|اشباع فروش/.test(status)?'signal-negative':'signal-neutral';}
function indicatorTable(title,rows){return `<section class="panel"><div class="panel-head"><h3>${esc(title)}</h3><span class="note">محاسبه محلی</span></div><div class="table-wrap"><table class="table indicator-table"><thead><tr><th>نام</th><th>مقدار</th><th>فاصله</th><th>وضعیت</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.name)}</td><td>${row.value==null?'—':fa(row.value)}</td><td>${row.distance==null?'—':`${fa(row.distance)}٪`}</td><td class="${signalClass(row.status)}">${esc(row.status||'—')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function renderAnalysis(payload){const {symbol,analysis,historySource}=payload,summary=analysis.summary||{positive:0,neutral:0,negative:0},context=analysis.context||{};$('#analysisScore').innerHTML=`<div class="score-box"><span>مثبت</span><strong>${fa(summary.positive)}</strong></div><div class="score-box"><span>خنثی</span><strong>${fa(summary.neutral)}</strong></div><div class="score-box"><span>منفی</span><strong>${fa(summary.negative)}</strong></div>`;const groups={oscillator:'نوسان‌گرها',volume:'حجم و جریان پول',trend:'میانگین‌های متحرک',volatility:'نوسان و فشردگی',composite:'امتیاز ترکیبی'},tables=Object.entries(groups).map(([key,title])=>indicatorTable(title,(analysis.rows||[]).filter(row=>row.group===key))).join('');$('#analysisContent').innerHTML=`<section class="panel"><div class="analysis-symbol-head"><div><h2>${esc(symbol.symbol)} <small>— ${esc(symbol.name||'')}</small></h2><p class="note">${esc(historySource)} · ${fa(analysis.candleCount)} کندل · آخرین کندل ${esc(analysis.asOf||'—')}</p></div><div class="analysis-meta"><span class="tag ${analysis.valid?'active':'insufficient'}">${analysis.valid?'داده کافی':'داده ناکافی'}</span><span class="tag ${signalClass(summary.label).replace('signal-','')}">${esc(summary.label||'—')}</span></div></div>${analysis.reason?`<p class="note">${esc(analysis.reason)}</p>`:''}</section><div class="indicator-summary"><div class="indicator-kpi"><span>قیمت زنده</span><strong>${fa(context.price)} ریال</strong></div><div class="indicator-kpi"><span>RSI 14</span><strong>${context.rsi14==null?'—':fa(context.rsi14)}</strong></div><div class="indicator-kpi"><span>MFI 14</span><strong>${context.mfi14==null?'—':fa(context.mfi14)}</strong></div><div class="indicator-kpi"><span>امتیاز بازیابی</span><strong>${context.tech_recovery_score==null?'—':`${fa(context.tech_recovery_score)} / ۸`}</strong></div></div><div class="indicator-sections">${tables}</div>`;}
async function loadAnalysis(){const symbol=$('#analysisSymbol').value.trim();if(!symbol)return msg('نماد را انتخاب کن.','error');$('#analysisContent').innerHTML='<div class="empty">در حال دریافت تاریخچه و محاسبه اندیکاتورها…</div>';try{renderAnalysis(await api(`/api/symbols/analysis?symbol=${encodeURIComponent(symbol)}`));}catch(error){$('#analysisContent').innerHTML=`<div class="empty">${esc(error.message)}</div>`;msg(error.message,'error');}}
$('#loadAnalysis').onclick=loadAnalysis;$('#analysisSymbol').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();loadAnalysis();}};
let searchTimer,activeSymbolInput=null;
function closeSymbolSuggestions(){const box=$('#ajaxSuggestions');box.classList.remove('show');box.innerHTML='';activeSymbolInput=null;}
function positionSuggestions(input){const rect=input.getBoundingClientRect(),box=$('#ajaxSuggestions');box.style.top=`${Math.min(innerHeight-330,rect.bottom+5)}px`;box.style.left=`${rect.left}px`;box.style.width=`${rect.width}px`;}
function bindSymbolAjax(input,onSelect=null){if(!input)return;input.setAttribute('autocomplete','off');input.addEventListener('input',()=>{clearTimeout(searchTimer);activeSymbolInput=input;searchTimer=setTimeout(async()=>{const query=input.value.trim(),box=$('#ajaxSuggestions');if(!query)return closeSymbolSuggestions();try{const {symbols}=await api(`/api/symbols?q=${encodeURIComponent(query)}`);if(activeSymbolInput!==input)return;box.innerHTML=symbols.map((x,i)=>`<button type="button" data-symbol-index="${i}"><span><b>${esc(x.symbol)}</b><small> — ${esc(x.name)}</small></span><small>${fa(x.lastPrice)} ریال</small></button>`).join('');positionSuggestions(input);box.classList.toggle('show',symbols.length>0);box.querySelectorAll('[data-symbol-index]').forEach(button=>button.onclick=()=>{const selected=symbols[Number(button.dataset.symbolIndex)];input.value=selected.symbol;closeSymbolSuggestions();onSelect?.(selected);});}catch(error){msg(error.message,'error');}},220);});input.addEventListener('focus',()=>{if(input.value.trim())input.dispatchEvent(new Event('input'));});}
$$('.symbol-ajax').forEach(input=>bindSymbolAjax(input,input.id==='symbol'?renderQuote:input.id==='analysisSymbol'?()=>$('#loadAnalysis').click():null));
bindNumericInputs();
document.addEventListener('click',event=>{if(!event.target.closest('.ajax-suggestions')&&!event.target.classList.contains('symbol-ajax'))closeSymbolSuggestions();});window.addEventListener('resize',()=>activeSymbolInput&&positionSuggestions(activeSymbolInput));
function updateAmount(){const value=Number($('#quantity').value||0)*Number($('#price').value||0)/10;$('#computed').value=value?`${fa(Math.round(value))} تومان`:'';}$('#quantity').oninput=updateAmount;$('#price').oninput=updateAmount;
function finishEdit(){editing=null;$('#save').textContent='ذخیره و فعال‌سازی';$('#cancelEdit').classList.add('hidden');}
function startLegacyEdit(item){editing={kind:'monitor',id:item.id};$('#title').value=item.title||'';$('#symbol').value=item.symbol||'';$('#action').value=item.actionType;$('#quantity').value=item.quantity||'';$('#price').value=item.proposedPrice||'';$('#maxAmount').value=item.maxAmountToman||'';$('#interval').value=item.intervalMinutes||5;$('#startAt').value=jalaliInput(new Date(item.startAt));$('#endAt').value=jalaliInput(new Date(item.endAt));tree=structuredClone(item.expression);$('#conditionText').value=item.sourceText||'';switchMode(item.inputMode==='text'?'text':'builder');renderBuilder();$('#save').textContent='ذخیره تغییرات';$('#cancelEdit').classList.remove('hidden');openPage('dashboard');scrollTo({top:0,behavior:'smooth'});updateAmount();}
function startRuleEdit(item){editing={kind:'rule',id:item.id,item};$('#title').value=item.name||'';$('#symbol').value=item.symbol||'';$('#quantity').value=item.actionParams?.quantity||'';$('#price').value=item.actionParams?.proposedPrice||'';$('#interval').value=item.intervalMinutes||5;$('#startAt').value=jalaliInput(new Date(item.startAt||Date.now()));$('#endAt').value=jalaliInput(new Date(item.endAt||Date.now()+86400000));$('#v2Scope').value=item.scope;$('#v2Severity').value=item.severity;$('#v2Action').value=item.action;$('#v2Cooldown').value=item.cooldownMinutes;$('#v2OncePerDay').checked=item.oncePerDay;v2Tree=structuredClone(item.expression);switchMode('v2');renderV2Builder();$('#save').textContent='ذخیره تغییرات';$('#cancelEdit').classList.remove('hidden');openPage('dashboard');scrollTo({top:0,behavior:'smooth'});updateAmount();}
$('#cancelEdit').onclick=()=>{finishEdit();msg('ویرایش لغو شد.');};
$('#parse').onclick=async()=>{try{const r=await api('/api/conditions/parse',{method:'POST',body:JSON.stringify({text:$('#conditionText').value})});$('#parsePreview').textContent=JSON.stringify(r.expression,null,2);$('#parsePreview').classList.remove('hidden');msg('شرط معتبر است.');}catch(e){msg(e.message,'error');}};
$('#refreshSymbols').onclick=async()=>{try{const r=await api('/api/symbols/refresh',{method:'POST'});msg(`${fa(r.count)} نماد به‌روزرسانی شد.`);await refreshStatus();}catch(e){msg(e.message,'error');}};
$('#save').onclick=async()=>{try{if(mode==='v2'){const scope=$('#v2Scope').value,severity=$('#v2Severity').value,body={name:$('#title').value||'Rule جدید',symbol:scope==='MARKET'?null:$('#symbol').value,scope,severity,expression:v2Tree,action:$('#v2Action').value,cooldownMinutes:Number($('#v2Cooldown').value),oncePerDay:$('#v2OncePerDay').checked,intervalMinutes:Number($('#interval').value),startAt:tehranIso($('#startAt').value),endAt:tehranIso($('#endAt').value),actionParams:{quantity:Number($('#quantity').value)||null,proposedPrice:Number($('#price').value)||null}};const edit=editing?.kind==='rule';await api(edit?`/api/rules/${editing.id}`:'/api/rules',{method:edit?'PUT':'POST',body:JSON.stringify(body)});finishEdit();msg(edit?'Rule ویرایش شد.':'Rule اندیکاتوری ذخیره و فعال شد.');await Promise.all([refreshStatus(),loadV2Rules()]);return;}const body={title:$('#title').value,symbol:$('#symbol').value,inputMode:mode,sourceText:$('#conditionText').value,expression:tree,actionType:$('#action').value,quantity:Number($('#quantity').value),proposedPrice:Number($('#price').value),maxAmountToman:Number($('#maxAmount').value)||null,startAt:tehranIso($('#startAt').value),endAt:tehranIso($('#endAt').value),intervalMinutes:Number($('#interval').value),cooldownMinutes:30};const edit=editing?.kind==='monitor';await api(edit?`/api/monitors/${editing.id}`:'/api/monitors',{method:edit?'PUT':'POST',body:JSON.stringify(body)});finishEdit();msg(edit?'پایش ویرایش شد.':'پایش ذخیره و فعال شد.');await Promise.all([refreshStatus(),loadMonitors()]);}catch(e){msg(e.message,'error');}};
$('#runDue').onclick=async()=>{try{const r=await api('/api/run-due',{method:'POST'});msg(`${fa(r.monitors||0)} پایش اجرا شد.`);await refreshStatus();}catch(e){msg(e.message,'error');}};

const actionLabels={BUY:'خرید',AVERAGE_DOWN:'میانگین کم‌کردن',SELL_STOP_LOSS:'حد زیان',SELL_TAKE_PROFIT:'سیو سود',ALERT:'هشدار',BUY_ALERT:'هشدار خرید',SELL_ALERT:'هشدار فروش',PARTIAL_PROFIT:'سیو سود بخشی',PROFIT_REVIEW:'بازبینی سود',EXIT_ALERT:'هشدار خروج',CANCEL_ORDER:'لغو سفارش',MOVE_STOP:'انتقال حد زیان',TRAILING_STOP:'حد زیان متحرک'},stateLabels={active:'فعال',paused:'متوقف',completed:'تکمیل',cancelled:'لغوشده',expired:'پایان‌یافته',inactive:'شرط برقرار نیست',insufficient:'داده ناکافی'};
function monitorCards(items,target){$(target).innerHTML=items.length?items.map(x=>`<article class="card"><div class="card-head"><label><input type="checkbox" data-monitor-select="${x.id}"> <strong>${esc(x.title)}</strong></label><span class="tag ${esc(x.status)}">${stateLabels[x.status]||x.status}</span></div><p><b>${esc(x.symbol)}</b> · ${actionLabels[x.actionType]||x.actionType}</p><div class="facts"><span>تعداد: ${fa(x.quantity)}</span><span>قیمت: ${fa(x.proposedPrice)} ریال</span><span>هر ${fa(x.intervalMinutes)} دقیقه</span><span>نتیجه: ${stateLabels[x.lastState]||'—'}</span><span>شروع: ${fmtDate(x.startAt)}</span><span>پایان: ${fmtDate(x.endAt)}</span></div><div class="actions"><button class="secondary small" data-edit-monitor="${x.id}">ویرایش</button><button class="secondary small" data-run="${x.id}">بررسی اکنون</button>${x.status==='active'?`<button class="secondary small" data-status="${x.id}:paused">توقف</button>`:`<button class="success small" data-status="${x.id}:active">فعال‌سازی</button>`}<button class="secondary small" data-status="${x.id}:cancelled">لغو</button><button class="danger small" data-delete="${x.id}">حذف</button></div></article>`).join(''):'<div class="empty">موردی وجود ندارد.</div>';bindMonitorActions(items,target);}
function bindMonitorActions(items=[],target='#monitors'){const root=$(target);[...root.querySelectorAll('[data-edit-monitor]')].forEach(b=>b.onclick=()=>startLegacyEdit(items.find(x=>x.id===Number(b.dataset.editMonitor))));[...root.querySelectorAll('[data-run]')].forEach(b=>b.onclick=async()=>{try{await api(`/api/monitors/${b.dataset.run}/run`,{method:'POST'});msg('بررسی انجام شد.');await loadMonitors();}catch(e){msg(e.message,'error');}});[...root.querySelectorAll('[data-status]')].forEach(b=>b.onclick=async()=>{const [id,status]=b.dataset.status.split(':');try{await api(`/api/monitors/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});await Promise.all([loadMonitors(),loadArchive(),refreshStatus()]);}catch(e){msg(e.message,'error');}});[...root.querySelectorAll('[data-delete]')].forEach(b=>b.onclick=async()=>{if(!confirm('این پایش و همه رویدادهای وابسته برای همیشه حذف شوند؟'))return;try{await api(`/api/monitors/${b.dataset.delete}`,{method:'DELETE'});msg('پایش حذف شد.');await Promise.all([loadMonitors(),loadArchive(),refreshStatus()]);}catch(e){msg(e.message,'error');}});}
async function loadMonitors(){try{const symbol=$('#monitorSymbolFilter').value.trim(),r=await api(`/api/monitors?symbol=${encodeURIComponent(symbol)}`);monitorCards(r.monitors,'#monitors');}catch(e){msg(e.message,'error');}}async function loadArchive(){try{const r=await api('/api/monitors?archive=1');monitorCards(r.monitors,'#archiveMonitors');}catch(e){msg(e.message,'error');}}
function v2RuleCards(items,target='#v2Rules',applyMainFilter=true){const symbol=applyMainFilter?$('#monitorSymbolFilter').value.trim():'',filtered=symbol?items.filter(x=>x.symbol===symbol):items,root=$(target);root.innerHTML=filtered.length?filtered.map(rule=>{const global=rule.visibility==='GLOBAL';return `<article class="card"><div class="card-head"><label>${global?'':`<input type="checkbox" data-rule-select="${rule.id}">`} <strong>${esc(rule.name)}</strong></label><span class="tag ${rule.status==='active'?'active':'paused'}">${global?'عمومی بازار':rule.status==='active'?'فعال':'متوقف'}</span></div><p><b>${esc(rule.symbol||'کل بازار')}</b> · ${esc(rule.severity)} · ${esc(rule.action)}</p><div class="facts"><span>شناسه: ${esc(rule.ruleId)}</span><span>هر ${fa(rule.intervalMinutes)} دقیقه</span><span>Cooldown: ${fa(rule.cooldownMinutes)} دقیقه</span><span>نتیجه: ${stateLabels[rule.state]||rule.state||'—'}</span></div>${global?'<p class="note">این قانون از بسته پیش‌فرض بازار است و برای همه کاربران اجرا می‌شود.</p>':`<div class="actions"><button class="secondary small" data-v2-edit="${rule.id}">ویرایش</button><button class="${rule.status==='active'?'secondary':'success'} small" data-v2-status="${rule.id}:${rule.status==='active'?'paused':'active'}">${rule.status==='active'?'توقف':'فعال‌سازی'}</button><button class="danger small" data-v2-delete="${rule.id}">حذف</button></div>`}</article>`;}).join(''):'<div class="empty">Ruleای یافت نشد.</div>';root.querySelectorAll('[data-v2-edit]').forEach(button=>button.onclick=()=>startRuleEdit(filtered.find(x=>x.id===Number(button.dataset.v2Edit))));root.querySelectorAll('[data-v2-status]').forEach(button=>button.onclick=async()=>{const [id,status]=button.dataset.v2Status.split(':');try{await api(`/api/rules/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});await loadV2Rules();if(target==='#symbolRules')$('#loadSymbolHistory').click();}catch(e){msg(e.message,'error');}});root.querySelectorAll('[data-v2-delete]').forEach(button=>button.onclick=async()=>{if(!confirm('این Rule و تاریخچه آن برای همیشه حذف شود؟'))return;try{await api(`/api/rules/${button.dataset.v2Delete}`,{method:'DELETE'});await Promise.all([loadV2Rules(),refreshStatus()]);if(target==='#symbolRules')$('#loadSymbolHistory').click();}catch(e){msg(e.message,'error');}});}
async function loadV2Rules(){try{v2RuleCards((await api('/api/rules')).rules);}catch(e){msg(e.message,'error');}}
const loadAllMonitors=()=>Promise.all([loadMonitors(),loadV2Rules()]);$('#applyMonitorFilter').onclick=loadAllMonitors;$('#reloadMonitors').onclick=loadAllMonitors;
$('[data-monitor-view="list"]').onclick=()=>setMonitorView('list');$('[data-monitor-view="grid"]').onclick=()=>setMonitorView('grid');function setMonitorView(view){for(const id of ['#monitors','#v2Rules'])$(id).classList.toggle('list-view',view==='list');$$('[data-monitor-view]').forEach(button=>button.classList.toggle('active',button.dataset.monitorView===view));localStorage.setItem('monitorView',view);}setMonitorView(localStorage.getItem('monitorView')||'grid');
$('#selectAllMonitoring').onchange=e=>$$('#page-monitors [data-monitor-select],#page-monitors [data-rule-select]').forEach(x=>x.checked=e.target.checked);
$('#deleteSelectedMonitoring').onclick=async()=>{const items=$$('#page-monitors [data-monitor-select]:checked').map(x=>({kind:'monitor',id:Number(x.dataset.monitorSelect)})).concat($$('#page-monitors [data-rule-select]:checked').map(x=>({kind:'rule',id:Number(x.dataset.ruleSelect)})));if(!items.length)return msg('هیچ موردی انتخاب نشده است.','error');if(!confirm(`${fa(items.length)} مورد انتخاب‌شده و تاریخچه وابسته حذف شوند؟`))return;try{const r=await api('/api/monitoring/bulk-delete',{method:'POST',body:JSON.stringify({items})});msg(`${fa(r.total)} مورد حذف شد.`);$('#selectAllMonitoring').checked=false;await Promise.all([loadAllMonitors(),refreshStatus()]);}catch(e){msg(e.message,'error');}};
$('#deleteAllMonitoring').onclick=async()=>{if(!confirm('همه پایش‌های فعال/متوقف و تمام Ruleهای v2 برای همیشه حذف شوند؟ آرشیو پایش‌ها باقی می‌ماند.'))return;if(!confirm('این عملیات قابل بازگشت نیست. حذف همه را تأیید می‌کنی؟'))return;try{const r=await api('/api/monitoring/bulk-delete',{method:'POST',body:JSON.stringify({all:true})});msg(`${fa(r.total)} پایش و Rule حذف شد.`);await Promise.all([loadAllMonitors(),refreshStatus()]);}catch(e){msg(e.message,'error');}};

function clearPortfolioForm(){$('#portfolioSymbol').value='';$('#portfolioSymbol').disabled=false;$('#portfolioQuantity').value='';$('#portfolioAvgPrice').value='';$('#portfolioBuyFee').value=formatNumericInput('1.262',true);$('#savePortfolio').textContent='ذخیره در سبد';$('#cancelPortfolioEdit').classList.add('hidden');}
function editPortfolio(position){$('#portfolioSymbol').value=position.symbol;$('#portfolioSymbol').disabled=true;$('#portfolioQuantity').value=formatNumericInput(position.quantity);$('#portfolioAvgPrice').value=formatNumericInput(position.avg_price);$('#portfolioBuyFee').value=formatNumericInput(position.buy_fee_pct??1.262,true);$('#savePortfolio').textContent='ذخیره تغییرات';$('#cancelPortfolioEdit').classList.remove('hidden');$('#portfolioQuantity').focus();scrollTo({top:$('#page-portfolio').offsetTop,behavior:'smooth'});}
function renderPortfolioSummary(summary){$('#portfolioSymbolCount').textContent=fa(summary.symbolCount);$('#portfolioCurrentValue').textContent=fa(Math.round(summary.totalCurrentValueRial));$('#portfolioTotalCost').textContent=fa(Math.round(summary.totalCostRial));const profit=$('#portfolioTotalProfit'),pct=$('#portfolioProfitPct');if(summary.totalProfitRial===null){profit.textContent='داده ناقص';pct.textContent=`قیمت ${fa(summary.missingPriceCount)} نماد موجود نیست`;profit.style.color='var(--amber)';return;}profit.textContent=`${summary.totalProfitRial>=0?'+':''}${fa(Math.round(summary.totalProfitRial))} ریال`;pct.textContent=`${summary.totalProfitPct>=0?'+':''}${fa(summary.totalProfitPct)}٪`;profit.style.color=summary.totalProfitRial>=0?'var(--green)':'var(--red)';}
let portfolioItems=[],portfolioSummary={};function sortPortfolio(items){const mode=$('#portfolioSort').value,numeric=(field,direction)=>(a,b)=>{const av=a[field],bv=b[field];if(av==null)return 1;if(bv==null)return-1;return direction*(av-bv);};return [...items].sort(mode==='profit_desc'?numeric('profit_pct',-1):mode==='profit_asc'?numeric('profit_pct',1):mode==='value_desc'?numeric('current_value_rial',-1):mode==='value_asc'?numeric('current_value_rial',1):(a,b)=>a.symbol.localeCompare(b.symbol,'fa'));}
function priceSourceLabel(position){if(!position.price_source)return'';const source=String(position.price_source).toLowerCase(),label=source.includes('rahavard')?'آخرین کندل رهاورد':source==='market'?'داده بازار':'آخرین کندل ذخیره‌شده',date=position.price_date?` · ${persianDigits(String(position.price_date).replace(/-/g,'/'))}`:'';return `${label}${date}`;}
function openSymbolProfile(symbol){$('#symbolHistoryInput').value=symbol;openPage('symbol');$('#loadSymbolHistory').click();}
function renderPortfolio(items=portfolioItems,summary=portfolioSummary){portfolioItems=items;portfolioSummary=summary;renderPortfolioSummary(summary);const sorted=sortPortfolio(items),root=$('#portfolioPositions');root.innerHTML=sorted.length?sorted.map(position=>`<article class="card clickable" tabindex="0" role="link" data-position-card="${esc(position.symbol)}"><div class="card-head"><strong>${esc(position.symbol)}</strong><span class="tag active">موجود در سبد</span></div><div class="facts"><span>تعداد: ${fa(position.quantity)} سهم</span><span>میانگین خرید: ${fa(position.avg_price)} ریال</span><span>کارمزد خرید: ${fa(position.buy_fee_pct)}٪</span><span>قیمت فعلی: ${position.current_price===null?'ناموجود':`${fa(position.current_price)} ریال`}<small class="note">${esc(priceSourceLabel(position))}</small></span><span>هزینه با کارمزد: ${fa(Math.round(position.cost_rial))} ریال</span><span>ارزش فعلی: ${position.current_value_rial===null?'ناموجود':`${fa(Math.round(position.current_value_rial))} ریال`}</span><span class="${position.profit_rial==null?'':position.profit_rial>=0?'profit-positive':'profit-negative'}">سود/زیان: ${position.profit_rial===null?'ناموجود':`${position.profit_rial>=0?'+':''}${fa(Math.round(position.profit_rial))} ریال (${position.profit_pct>=0?'+':''}${fa(position.profit_pct)}٪)`}</span><span>آخرین ویرایش: ${fmtDate(position.updated_at)}</span></div><div class="actions"><button class="secondary small" data-edit-position="${esc(position.symbol)}">ویرایش</button><button class="danger small" data-delete-position="${esc(position.symbol)}">حذف از سبد</button></div></article>`).join(''):'<div class="empty">هنوز سهمی در سبد تعریف نشده است.</div>';root.querySelectorAll('[data-position-card]').forEach(card=>{card.onclick=event=>{if(event.target.closest('button,input,a'))return;openSymbolProfile(card.dataset.positionCard);};card.onkeydown=event=>{if((event.key==='Enter'||event.key===' ')&&!event.target.closest('button,input,a')){event.preventDefault();openSymbolProfile(card.dataset.positionCard);}};});root.querySelectorAll('[data-edit-position]').forEach(button=>button.onclick=()=>editPortfolio(items.find(position=>position.symbol===button.dataset.editPosition)));root.querySelectorAll('[data-delete-position]').forEach(button=>button.onclick=async()=>{const symbol=button.dataset.deletePosition;if(!confirm(`${symbol} از سبد حذف شود؟ پس از حذف، هشدار فروش این نماد ارسال نمی‌شود.`))return;try{await api(`/api/portfolio/${encodeURIComponent(symbol)}`,{method:'DELETE'});if($('#portfolioSymbol').value===symbol)clearPortfolioForm();msg(`${symbol} از سبد حذف شد.`);await loadPortfolio();}catch(error){msg(error.message,'error');}});}
async function loadPortfolio(){try{const {positions,summary}=await api('/api/portfolio');renderPortfolio(positions,summary);}catch(error){msg(error.message,'error');}}
$('#portfolioSort').value=localStorage.getItem('portfolioSort')||'symbol';$('#portfolioSort').onchange=()=>{localStorage.setItem('portfolioSort',$('#portfolioSort').value);renderPortfolio();};function setPortfolioView(view){$('#portfolioPositions').classList.toggle('list-view',view==='list');$$('[data-portfolio-view]').forEach(button=>button.classList.toggle('active',button.dataset.portfolioView===view));localStorage.setItem('portfolioView',view);}$$('[data-portfolio-view]').forEach(button=>button.onclick=()=>setPortfolioView(button.dataset.portfolioView));setPortfolioView(localStorage.getItem('portfolioView')||'grid');
$('#savePortfolio').onclick=async()=>{const symbol=$('#portfolioSymbol').value.trim(),quantity=numberValue($('#portfolioQuantity').value),avgPrice=numberValue($('#portfolioAvgPrice').value),buyFeePct=numberValue($('#portfolioBuyFee').value);if(!symbol)return msg('نماد را جست‌وجو و انتخاب کن.','error');if(!Number.isInteger(quantity)||quantity<=0)return msg('تعداد سهم باید عدد صحیح بزرگ‌تر از صفر باشد.','error');if(!Number.isFinite(avgPrice)||avgPrice<=0)return msg('میانگین خرید باید بزرگ‌تر از صفر باشد.','error');if(!Number.isFinite(buyFeePct)||buyFeePct<0||buyFeePct>10)return msg('کارمزد خرید باید بین صفر و ۱۰ درصد باشد.','error');try{await api('/api/portfolio',{method:'PUT',body:JSON.stringify({symbol,quantity,avgPrice,buyFeePct})});msg(`${symbol} در سبد ذخیره شد.`);clearPortfolioForm();await loadPortfolio();}catch(error){msg(error.message,'error');}};
$('#cancelPortfolioEdit').onclick=clearPortfolioForm;$('#reloadPortfolio').onclick=loadPortfolio;

function renderEvents(items,target='#events'){$(target).innerHTML=items.length?items.map(x=>{const price=x.snapshot?.lastPrice??x.snapshot?.price;return `<div class="event"><div class="line"><strong>${esc(x.symbol)} — ${actionLabels[x.action_type]||x.action_type}</strong><span class="tag ${esc(x.state)}">${stateLabels[x.state]||x.state}</span></div><div class="note">${fmtDate(x.created_at)} · ${x.telegram_sent?'پیام ارسال شد':'پیام ارسال نشد'} · آخرین قیمت ${price==null?'—':fa(price)} ریال</div></div>`;}).join(''):'<div class="empty">نتیجه‌ای ثبت نشده است.</div>';}
async function loadEvents(){try{const q=new URLSearchParams({limit:'500',symbol:$('#eventSymbolFilter').value.trim(),sent:$('#eventSentFilter').value}),r=await api(`/api/events?${q}`);renderEvents(r.events);}catch(e){msg(e.message,'error');}}$('#applyEventFilter').onclick=loadEvents;
$('#loadSymbolHistory').onclick=async()=>{const symbol=$('#symbolHistoryInput').value.trim();if(!symbol)return msg('نماد را وارد کن.','error');try{const [detail,active,rules,events]=await Promise.all([api(`/api/symbols/detail?symbol=${encodeURIComponent(symbol)}`),api(`/api/monitors?symbol=${encodeURIComponent(symbol)}`),api(`/api/rules?symbol=${encodeURIComponent(symbol)}`),api(`/api/events?limit=500&symbol=${encodeURIComponent(symbol)}`)]);$('#symbolHistoryQuote').innerHTML='<div id="historyQuoteBox" class="quote-grid"></div>';renderQuote(detail.symbol,'#historyQuoteBox');monitorCards(active.monitors,'#symbolMonitors');v2RuleCards(rules.rules,'#symbolRules',false);renderEvents(events.events,'#symbolEvents');}catch(e){msg(e.message,'error');}};

$('#bulkFile').onchange=async e=>{const file=e.target.files[0];if(file)$('#bulkText').value=await file.text();};
async function bulk(preview){try{const text=$('#bulkText').value,parsed=text.trim().startsWith('{')?JSON.parse(text):null,isRules=Array.isArray(parsed?.rules)||Boolean(parsed?.installPack),path=isRules?(preview?'/api/rules/import/preview':'/api/rules/import'):(preview?'/api/monitors/import/preview':'/api/monitors/import'),r=await api(path,{method:'POST',body:JSON.stringify({text})}),items=isRules?r.rules:r.monitors,count=r.count??r.total??items.length,label=isRules?'قانون':'پایش';$('#bulkResult').innerHTML=`<div class="panel" style="margin-top:12px"><b>${fa(count)} ${label} ${preview?'معتبر و آماده ورود است':isRules?`بررسی شد؛ ${fa(r.added)} مورد جدید ساخته شد`:'ساخته شد'}.</b><div class="note">${items.map(x=>`${esc(x.symbol||'کل بازار')} — ${esc(x.name||x.title)}${isRules&&!x.enabled?' — غیرفعال':''}`).join('<br>')}</div></div>`;msg(preview?'پیش‌نمایش معتبر است.':'ورود گروهی کامل شد.');await Promise.all([refreshStatus(),isRules?loadV2Rules():loadMonitors()]);}catch(e){msg(e.message,'error');}}$('#bulkPreviewBtn').onclick=()=>bulk(true);$('#bulkImportBtn').onclick=()=>{if(confirm('همه موارد معتبر ایجاد شوند؟ موارد تکراری دوباره ساخته نمی‌شوند.'))bulk(false);};

function newBot(){return {id:crypto.randomUUID(),name:'ربات جدید',token:'',chatId:'',enabled:true,primary:!settings.telegramBots.length};}function newApi(){return {id:crypto.randomUUID(),name:'BRSAPI جدید',apiKey:'',enabled:true,priority:settings.apiProviders.length+1,baseUrl:'https://Api.BrsApi.ir'};}
function renderSettings(){const bots=settings.telegramBots||[],apis=settings.apiProviders||[];$('#apiMode').value=settings.apiMode||'fallback';$('#botSettings').innerHTML=bots.map((x,i)=>`<div class="setting-item" data-bot-row data-id="${esc(x.id)}"><div class="setting-grid"><div class="field"><label>نام</label><input data-k="name" value="${esc(x.name)}"></div><div class="field"><label>Bot Token</label><input data-k="token" type="password" value="${esc(x.token)}"></div><div class="field"><label>Chat ID</label><input data-k="chatId" value="${esc(x.chatId)}"></div><div class="actions"><label><input data-k="enabled" type="checkbox" ${x.enabled?'checked':''}> فعال</label><label><input name="primaryBot" data-k="primary" type="radio" ${x.primary?'checked':''}> اصلی</label><button class="danger small" data-remove-bot="${i}">حذف</button></div></div></div>`).join('')||'<div class="empty">رباتی تعریف نشده است.</div>';$('#apiSettings').innerHTML=apis.map((x,i)=>`<div class="setting-item" data-api-row data-id="${esc(x.id)}"><div class="setting-grid"><div class="field"><label>نام</label><input data-k="name" value="${esc(x.name)}"></div><div class="field"><label>API Key</label><input data-k="apiKey" type="password" value="${esc(x.apiKey)}"></div><div class="field"><label>آدرس پایه</label><input data-k="baseUrl" dir="ltr" value="${esc(x.baseUrl)}"></div><div class="field"><label>اولویت</label><input data-k="priority" type="number" min="1" value="${x.priority||1}"><label><input data-k="enabled" type="checkbox" ${x.enabled?'checked':''}> فعال</label><button class="danger small" data-remove-api="${i}">حذف</button></div></div></div>`).join('')||'<div class="empty">کلیدی تعریف نشده است.</div>';$$('[data-remove-bot]').forEach(b=>b.onclick=()=>{settings.telegramBots.splice(Number(b.dataset.removeBot),1);renderSettings();});$$('[data-remove-api]').forEach(b=>b.onclick=()=>{settings.apiProviders.splice(Number(b.dataset.removeApi),1);renderSettings();});}
function collectSettings(){const bots=$$('[data-bot-row]').map(row=>({id:row.dataset.id,name:row.querySelector('[data-k=name]').value,token:row.querySelector('[data-k=token]').value,chatId:row.querySelector('[data-k=chatId]').value,enabled:row.querySelector('[data-k=enabled]').checked,primary:row.querySelector('[data-k=primary]').checked}));const apis=$$('[data-api-row]').map(row=>({id:row.dataset.id,name:row.querySelector('[data-k=name]').value,apiKey:row.querySelector('[data-k=apiKey]').value,baseUrl:row.querySelector('[data-k=baseUrl]').value,priority:Number(row.querySelector('[data-k=priority]').value),enabled:row.querySelector('[data-k=enabled]').checked}));return {timezone:tz,apiMode:$('#apiMode').value,telegramBots:bots,apiProviders:apis};}
async function loadSettings(){try{settings=(await api('/api/settings')).settings;renderSettings();}catch(e){msg(e.message,'error');}}$('#addBot').onclick=()=>{settings.telegramBots.push(newBot());renderSettings();};$('#addApi').onclick=()=>{settings.apiProviders.push(newApi());renderSettings();};
async function loadHistoryStatus(){try{const r=await api('/api/history/status'),last=r.lastImport;$('#historyStatus').textContent=last?`${fa(last.importedSymbols)} نماد · ${esc(last.latestDate||'—')}`:'بدون سابقه ورود';}catch(e){msg(e.message,'error');}}
function renderHistoryImport(r){$('#historyImportResult').innerHTML=`<b>${fa(r.importedSymbols)} نماد و ${fa(r.importedCandles)} کندل وارد شد.</b><br>تطبیق‌نشده: ${fa(r.unmatched.length)} · فایل نامعتبر: ${fa(r.invalid.length)} · آخرین تاریخ: ${esc(r.latestDate||'—')}`;const box=$('#historyUnmatched'),rows=$('#historyMappingRows');box.classList.toggle('hidden',!r.unmatched.length);rows.innerHTML=r.unmatched.slice(0,100).map(x=>`<div class="setting-item"><div class="setting-grid"><div><b dir="ltr">${esc(x.ticker)}</b><div class="note">${esc(x.lastDate)} · ${fa(x.lastClose)} ریال</div></div><div class="field span2"><label>نماد فارسی</label><input class="symbol-ajax" data-history-ticker="${esc(x.ticker)}" placeholder="جستجوی نماد"></div><small>${x.candidates?.length?`پیشنهاد: ${x.candidates.map(esc).join('، ')}`:'بدون پیشنهاد'}</small></div></div>`).join('');$$('[data-history-ticker]').forEach(input=>bindSymbolAjax(input));}
$('#importHistory').onclick=async()=>{const file=$('#historyZip').files[0];if(!file)return msg('فایل ZIP را انتخاب کن.','error');if(file.size>35_000_000)return msg('حجم ZIP بیشتر از ۳۵ مگابایت است.','error');const button=$('#importHistory');button.disabled=true;button.textContent='در حال ورود…';try{const response=await fetch('/api/history/import',{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/zip'},body:file}),body=await response.json();if(!response.ok)throw new Error(body.error);renderHistoryImport(body);await loadHistoryStatus();msg('ورود تاریخچه کامل شد.');}catch(e){msg(e.message,'error');}finally{button.disabled=false;button.textContent='بارگذاری تاریخچه';}};
$('#saveHistoryMappings').onclick=async()=>{const mappings=$$('[data-history-ticker]').filter(x=>x.value.trim()).map(x=>({ticker:x.dataset.historyTicker,symbol:x.value.trim()}));if(!mappings.length)return msg('حداقل یک نگاشت را وارد کن.','error');try{await api('/api/history/mappings',{method:'POST',body:JSON.stringify({mappings})});msg('نگاشت‌ها ذخیره شد؛ ZIP را دوباره بارگذاری کن.');}catch(e){msg(e.message,'error');}};
$('#saveSettings').onclick=async()=>{try{settings=(await api('/api/settings',{method:'PUT',body:JSON.stringify(collectSettings())})).settings;renderSettings();msg('تنظیمات اتصال ذخیره شد.');await refreshStatus();}catch(e){msg(e.message,'error');}};
$('#testTelegram').onclick=async()=>{try{const r=await api('/api/settings/test/telegram',{method:'POST',body:'{}'});msg(`پیام آزمایشی با ${fa(r.sent)} ربات ارسال شد.`);}catch(e){msg(e.message,'error');}};$('#testBrs').onclick=async()=>{try{const r=await api('/api/settings/test/brsapi',{method:'POST',body:'{}'});msg(`${fa(r.count)} نماد از ${r.provider||'BRSAPI'} دریافت شد.`);}catch(e){msg(e.message,'error');}};
$('#changePassword').onclick=async()=>{if(!confirm('رمز تغییر کند و همه نشست‌ها بسته شوند؟'))return;try{await api('/api/auth/password',{method:'PUT',body:JSON.stringify({password:$('#newAdminPassword').value})});logout(false);msg('رمز تغییر کرد. با رمز جدید وارد شو.');}catch(e){msg(e.message,'error');}};

function renderUsers(users){$('#usersList').innerHTML=users.map(user=>`<div class="setting-item" data-user-id="${user.id}"><div class="setting-grid"><div><b>${esc(user.display_name)}</b><div class="note" dir="ltr">${esc(user.username)}</div></div><div class="field"><label>نقش</label><select data-user-role><option value="NORMAL" ${user.role==='NORMAL'?'selected':''}>کاربر معمولی</option><option value="SENIOR" ${user.role==='SENIOR'?'selected':''}>کاربر ارشد</option></select></div><div class="field"><label>رمز جدید؛ اختیاری</label><input data-user-password type="password" placeholder="بدون تغییر"></div><div class="actions"><label><input data-user-active type="checkbox" ${user.active?'checked':''}> فعال</label><button data-save-user class="secondary small">ذخیره</button></div></div></div>`).join('')||'<div class="empty">کاربری وجود ندارد.</div>';$$('[data-save-user]').forEach(button=>button.onclick=async()=>{const row=button.closest('[data-user-id]'),id=Number(row.dataset.userId),user=users.find(x=>x.id===id);try{await api(`/api/users/${id}`,{method:'PUT',body:JSON.stringify({displayName:user.display_name,role:row.querySelector('[data-user-role]').value,active:row.querySelector('[data-user-active]').checked,password:row.querySelector('[data-user-password]').value})});msg('کاربر به‌روزرسانی شد.');await loadUsers();}catch(error){msg(error.message,'error');}});}
async function loadUsers(){if(currentUser?.role!=='SENIOR')return;try{renderUsers((await api('/api/users')).users);}catch(error){msg(error.message,'error');}}
$('#reloadUsers').onclick=loadUsers;$('#createUser').onclick=async()=>{try{await api('/api/users',{method:'POST',body:JSON.stringify({username:$('#newUsername').value.trim(),displayName:$('#newUserDisplayName').value.trim(),role:$('#newUserRole').value,password:$('#newUserPassword').value})});$('#newUsername').value='';$('#newUserDisplayName').value='';$('#newUserPassword').value='';msg('کاربر جدید ساخته شد.');await loadUsers();}catch(error){msg(error.message,'error');}};

$('#downloadBackup').onclick=async()=>{try{const password=$('#backupPassword').value,response=await fetch('/api/backup',{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json'},body:JSON.stringify({password})});if(!response.ok)throw new Error((await response.json()).error);const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`bourse-monitor-${new Date().toISOString().slice(0,10)}.bmon`;a.click();URL.revokeObjectURL(url);msg('فایل پشتیبان رمزگذاری‌شده دریافت شد.');}catch(e){msg(e.message,'error');}};
$('#restoreBackup').onclick=async()=>{const file=$('#restoreFile').files[0];if(!file)return msg('فایل پشتیبان را انتخاب کن.','error');if(!confirm(currentUser?.role==='SENIOR'?'همه داده‌های فعلی سامانه جایگزین شوند؟':'داده‌های شخصی فعلی شما جایگزین شوند؟'))return;try{const response=await fetch('/api/restore',{method:'POST',headers:{authorization:`Bearer ${token}`,'x-backup-passphrase':$('#restorePassword').value},body:file});const body=await response.json();if(!response.ok)throw new Error(body.error);if(body.relogin)logout(false);else await initApp();msg(body.message);}catch(e){msg(e.message,'error');}};

async function refreshStatus(){try{const s=await api('/api/status');$('#provider').textContent=`داده: ${s.provider}${s.lastProvider?` / ${s.lastProvider}`:''}`;$('#providerDot').classList.toggle('good',s.provider==='brsapi');$('#telegram').textContent=`تلگرام: ${s.telegramConfigured?'آماده':'تنظیم نشده'}`;$('#telegramDot').classList.toggle('good',s.telegramConfigured);$('#lastRun').textContent=`آخرین اجرا: ${s.lastRunAt?fmtDate(s.lastRunAt):'—'}`;$('#statMonitors').textContent=fa(Number(s.stats.monitors||0)+Number(s.stats.rules||0));$('#statAlerts').textContent=fa(s.stats.alerts);$('#statSymbols').textContent=fa(s.stats.symbols);$('#statEvents').textContent=fa(s.stats.events);}catch(e){if(token)msg(e.message,'error');}}
async function initApp(){try{const me=await api('/api/auth/me');currentUser=me.user;$$('.senior-only').forEach(element=>element.classList.toggle('hidden',currentUser.role!=='SENIOR'));$('#currentUserLabel').textContent=`${currentUser.displayName} · ${currentUser.role==='SENIOR'?'کاربر ارشد':'کاربر معمولی'}`;[meta]=await Promise.all([api('/api/meta'),refreshStatus()]);$('#action').innerHTML=meta.actions.map(x=>`<option value="${x.value}">${esc(x.label)}</option>`).join('');$('#v2Action').innerHTML=(meta.actionsV2||[]).map(x=>`<option value="${x.value}">${esc(x.label)}</option>`).join('');renderBuilder();renderV2Builder();await Promise.all([loadMonitors(),loadV2Rules(),loadPortfolio(),loadArchive(),loadEvents()]);showApp();}catch(e){msg(e.message,'error');}}
if(token)initApp();else showLogin();setInterval(()=>{if(token)refreshStatus();},30000);
